[
        {
          "id": "ex-generative-lda-and-logistic-share-a-boundary",
          "kind": "example",
          "title": "A Gaussian LDA model and a conditional logistic model can share a decision boundary",
          "deps": [
            "thm-lda-and-qda-log-posterior-scores",
            "def-binary-logistic-and-multiclass-softmax-models",
            "def-axiom-of-choice"
          ],
          "statement": "Assume AC. In one dimension, take LDA classes $1$ and $2$ with equal priors and conditional laws $X\\mid Y=1\\sim N_1(-1,1)$ and $X\\mid Y=2\\sim N_1(1,1)$. Recode class $1$ as binary label $0$ and class $2$ as binary label $1$ in a conditional logistic model with $\\Pr(Y=1\\mid x)=\\sigma(2x)$. Both classifiers have tie boundary $x=0$ and agree on both sides of that boundary; ties select class $1$ (binary label $0$). This equality of boundaries for these parameters does not identify the two estimation procedures or equate their coefficients in general.\n\nThe number line marks the two Gaussian means and their posterior tie boundary; the score calculation below establishes the boundary.\n\n```tikz\n\\begin{tikzpicture}[x=1.25cm,y=1cm]\n  \\draw[->] (-2.1,0) -- (2.1,0) node[right] {$x$};\n  \\fill (-1,0) circle (2pt);\n  \\fill (1,0) circle (2pt);\n  \\draw[dashed] (0,-0.32) -- (0,0.42);\n  \\node[below] at (-1,0) {$\\mu_1=-1$};\n  \\node[below] at (1,0) {$\\mu_2=1$};\n  \\node[above] at (0,0.42) {$x=0$};\n\\end{tikzpicture}\n```",
          "strategy": "Substitute the one-dimensional Gaussian means and equal priors into the LDA score difference, then compare it with the chosen logistic threshold.",
          "proof_strategy": "direct",
          "sources": {
            "references": [
              {
                "title": "Hastie, Tibshirani, and Friedman, The Elements of Statistical Learning, 2nd ed., corrected 12th printing",
                "url": "https://drive.google.com/uc?export=download&id=1--Wo5Hcl2y_v3DL-tGgcJHRPdtjiVYjS"
              },
              {
                "title": "Stanford CS229 Spring 2022 lecture notes",
                "url": "https://cs229.stanford.edu/lectures-spring2022/main_notes.pdf"
              }
            ]
          },
          "provenance": {
            "statement": "ai-generated",
            "proof": "ai-generated",
            "generation": {
              "role": "example"
            }
          },
          "dependency_level": 2,
          "justified_by": []
        },
        {
          "id": "ex-separated-logistic-sample-has-unattained-supremum",
          "kind": "example",
          "title": "A strictly separated two-point sample has an unattained logistic likelihood supremum",
          "deps": [
            "thm-complete-separation-precludes-finite-logistic-mle",
            "def-binary-logistic-log-likelihood-and-l1-penalty"
          ],
          "statement": "Take two one-dimensional observations $(x_1,y_1)=(-1,0)$ and $(x_2,y_2)=(1,1)$ with an intercept in the design. The augmented rows are $(1,-1)$ and $(1,1)$, and the vector $(0,1)$ strictly separates them. Along coefficients $\\beta(t)=(0,t)$ with $t>0$, the log-likelihood is $-2\\log(1+e^{-t})$, which tends to zero while remaining negative for every finite $t$. The sample therefore has an unattained supremum at zero.",
          "strategy": "Verify a strict separator and compute the diverging-slope log-likelihood explicitly.",
          "proof_strategy": "direct",
          "sources": {
            "references": [
              {
                "title": "Hastie, Tibshirani, and Friedman, The Elements of Statistical Learning, 2nd ed., corrected 12th printing",
                "url": "https://drive.google.com/uc?export=download&id=1--Wo5Hcl2y_v3DL-tGgcJHRPdtjiVYjS"
              }
            ]
          },
          "provenance": {
            "statement": "ai-generated",
            "proof": "ai-generated",
            "generation": {
              "role": "example"
            }
          },
          "dependency_level": 4,
          "justified_by": []
        },
        {
          "id": "ex-nonseparable-perceptron-cycles",
          "kind": "example",
          "title": "Two contradictory labels make the cyclic perceptron repeat a two-pass cycle",
          "deps": [
            "alg-cyclic-perceptron"
          ],
          "statement": "Use the ordered one-dimensional sample $(x_1,y_1)=(0,+1)$, $(x_2,y_2)=(0,-1)$. It is not separable by an affine score because both observations have the same augmented input $(0,1)$ and require opposite strict signs. For the zero-initialized cyclic perceptron, every pass updates on both observations and returns the weight vector to zero, so no no-update pass occurs.",
          "strategy": "Apply both updates in order and show that every pass returns to the zero weight vector.",
          "proof_strategy": "direct",
          "sources": {
            "references": [
              {
                "title": "Hastie, Tibshirani, and Friedman, The Elements of Statistical Learning, 2nd ed., corrected 12th printing",
                "url": "https://drive.google.com/uc?export=download&id=1--Wo5Hcl2y_v3DL-tGgcJHRPdtjiVYjS"
              },
              {
                "title": "Stanford CS229 Spring 2022 lecture notes",
                "url": "https://cs229.stanford.edu/lectures-spring2022/main_notes.pdf"
              }
            ]
          },
          "provenance": {
            "statement": "ai-generated",
            "proof": "ai-generated",
            "generation": {
              "role": "example"
            }
          },
          "dependency_level": 1,
          "justified_by": []
        }
      ]

