[
        {
          "id": "def-mahalanobis-pseudometric",
          "kind": "definition",
          "page": "ml02-metric-learning",
          "deps": [
            "thm-of-square-roots"
          ],
          "dependency_level": 0,
          "title": "Mahalanobis pseudometric induced by a positive-semidefinite matrix",
          "justified_by": [],
          "provenance": {
            "statement": "literature-derived",
            "proof": "not-applicable"
          },
          "sources": {
            "scraped": [],
            "references": [
              {
                "title": "Kilian Q. Weinberger and Lawrence K. Saul, Distance Metric Learning for Large Margin Nearest Neighbor Classification, JMLR 10 (2009), 207–244",
                "url": "https://jmlr.org/papers/volume10/weinberger09a/weinberger09a.pdf"
              },
              {
                "title": "Aurélien Bellet, Amaury Habrard, and Marc Sebban, A Survey on Metric Learning for Feature Vectors and Structured Data, arXiv:1306.6709v4 (2014)",
                "url": "https://arxiv.org/pdf/1306.6709"
              }
            ]
          },
          "landmark": false,
          "aliases": [],
          "statement": "Fix an integer $d\\ge1$. A real matrix $M\\in\\mathbb R^{d\\times d}$ is positive semidefinite, written $M\\succeq0$, when it is symmetric and $v^{T}Mv\\ge0$ for every $v\\in\\mathbb R^d$. For $x,x'\\in\\mathbb R^d$, define the squared Mahalanobis distance and its nonnegative square root by\n\n$$q_M(x,x') := (x-x')^{T}M(x-x'),\\qquad d_M(x,x') := \\sqrt{q_M(x,x')}.$$\n\nThe square root is defined because $q_M(x,x')\\ge0$. A pseudometric is a nonnegative symmetric function that vanishes on the diagonal and satisfies the triangle inequality, but may assign distance zero to distinct points. The function $d_M$ is called the Mahalanobis pseudometric associated with $M$; $q_M=d_M^2$ is its squared-distance form. The theorem on this page proves the pseudometric properties and the equivalent linear-feature representation."
        },
        {
          "id": "lem-symmetric-matrix-frobenius-isometry",
          "kind": "lemma",
          "page": "ml02-metric-learning",
          "deps": [
            "def-frobenius-matrix-norm",
            "def-euclidean-inner-product",
            "thm-of-square-roots"
          ],
          "dependency_level": 0,
          "title": "Symmetric matrices are Euclidean under the Frobenius norm",
          "justified_by": [],
          "provenance": {
            "statement": "ai-altered",
            "proof": "ai-altered"
          },
          "sources": {
            "scraped": [],
            "references": [
              {
                "title": "Nicholas J. Higham, Computing a Nearest Symmetric Positive Semidefinite Matrix, Linear Algebra and its Applications 103 (1988), 103–118",
                "url": "https://nhigham.com/wp-content/uploads/2023/10/high88d.pdf"
              },
              {
                "title": "David Bindel, Matrix Computations, CS 6210, Matrix Nearness Problems, Fall 2022",
                "url": "https://www.cs.cornell.edu/courses/cs6210/2022fa/lec/2022-10-06.pdf"
              }
            ]
          },
          "proof_strategy": "direct",
          "landmark": false,
          "aliases": [],
          "statement": "Let $d\\ge1$, let $\\mathbb S^d$ be the real vector space of symmetric $d\\times d$ matrices, and set $m=d(d+1)/2$. Equip $\\mathbb S^d$ with the Frobenius inner product $\\langle A,B\\rangle_F:=\\sum_{i=1}^{d}\\sum_{j=1}^{d}A_{ij}B_{ij}$ and its induced norm. Define $\\operatorname{svec}:\\mathbb S^d\\to\\mathbb R^m$ by listing $A_{11},\\ldots,A_{dd}$ first, followed by $\\sqrt2 A_{ij}$ for $1\\le i<j\\le d$ in lexicographic order. Then $\\operatorname{svec}$ is a linear bijection and preserves inner products and norms; in particular, $\\|\\operatorname{svec}(A)-\\operatorname{svec}(B)\\|_2=\\|A-B\\|_F$ for all $A,B\\in\\mathbb S^d$."
        },
        {
          "id": "thm-frobenius-projection-onto-psd-cone-is-spectral-clipping",
          "kind": "theorem",
          "page": "ml02-metric-learning",
          "deps": [
            "cor-real-spectral-theorem-for-self-adjoint-endomorphisms",
            "thm-non-negative-operator-characterisations",
            "prop-operator-positivity-agrees-with-form-positivity-over-the-reals",
            "thm-spectral-and-frobenius-norms-are-unitarily-invariant-with-singular-value-formulas-and-rank-comparison",
            "def-frobenius-matrix-norm"
          ],
          "dependency_level": 0,
          "title": "Frobenius projection onto the positive-semidefinite cone is spectral clipping",
          "justified_by": [],
          "provenance": {
            "statement": "ai-altered",
            "proof": "ai-altered"
          },
          "sources": {
            "scraped": [],
            "references": [
              {
                "title": "Nicholas J. Higham, Computing a Nearest Symmetric Positive Semidefinite Matrix, Linear Algebra and its Applications 103 (1988), 103–118",
                "url": "https://nhigham.com/wp-content/uploads/2023/10/high88d.pdf"
              },
              {
                "title": "David Bindel, Matrix Computations, CS 6210, Matrix Nearness Problems, Fall 2022",
                "url": "https://www.cs.cornell.edu/courses/cs6210/2022fa/lec/2022-10-06.pdf"
              },
              {
                "title": "Kilian Q. Weinberger and Lawrence K. Saul, Distance Metric Learning for Large Margin Nearest Neighbor Classification, JMLR 10 (2009), 207–244",
                "url": "https://jmlr.org/papers/volume10/weinberger09a/weinberger09a.pdf"
              }
            ]
          },
          "proof_strategy": "direct",
          "landmark": false,
          "aliases": [],
          "statement": "Let $d\\ge1$ and let $A\\in\\mathbb R^{d\\times d}$ be symmetric. There exists an orthogonal eigendecomposition $A=U\\operatorname{diag}(\\lambda_1,\\ldots,\\lambda_d)U^T$. For any such decomposition define $\\lambda_i^+=\\max\\{\\lambda_i,0\\}$ and $A_+=U\\operatorname{diag}(\\lambda_1^+,\\ldots,\\lambda_d^+)U^T$. Let $\\mathbb S_+^d$ be the set of real symmetric matrices $Z$ with $v^TZv\\ge0$ for every $v\\in\\mathbb R^d$, and let $\\|B\\|_F=(\\sum_{i,j}B_{ij}^2)^{1/2}$. Then $A_+$ is the unique minimizer of $\\|A-Z\\|_F$ over $Z\\in\\mathbb S_+^d$, so its value is independent of the chosen orthogonal eigendecomposition."
        },
