          ],
          "dependency_level": 1,
          "title": "The Mahalanobis distance is a pseudometric and comes from a linear feature map",
          "justified_by": [],
          "provenance": {
            "statement": "ai-altered",
            "proof": "ai-altered"
          },
          "sources": {
            "scraped": [],
            "references": [
              {
                "title": "Kilian Q. Weinberger and Lawrence K. Saul, Distance Metric Learning for Large Margin Nearest Neighbor Classification, JMLR 10 (2009), 207–244",
                "url": "https://jmlr.org/papers/volume10/weinberger09a/weinberger09a.pdf"
              },
              {
                "title": "Aurélien Bellet, Amaury Habrard, and Marc Sebban, A Survey on Metric Learning for Feature Vectors and Structured Data, arXiv:1306.6709v4 (2014)",
                "url": "https://arxiv.org/pdf/1306.6709"
              }
            ]
          },
          "proof_strategy": "direct",
          "landmark": false,
          "aliases": [],
          "statement": "Let $d\\ge1$ and let $M\\in\\mathbb R^{d\\times d}$ be real symmetric and positive semidefinite, meaning $v^TMv\\ge0$ for every $v\\in\\mathbb R^d$. Define $q_M(x,x')=(x-x')^TM(x-x')$ and $d_M(x,x')=\\sqrt{q_M(x,x')}$. Then there is a real matrix $L\\in\\mathbb R^{d\\times d}$ with $M=L^TL$ and, for all $x,x'\\in\\mathbb R^d$, $d_M(x,x')=\\|Lx-Lx'\\|_2$. Consequently $d_M$ is nonnegative, symmetric, zero on the diagonal, and satisfies the triangle inequality, without asserting separation of distinct points."
