          "id": "lem-roots-of-unity-fft-complexity",
          "kind": "lemma",
          "title": "Roots-of-unity orthogonality and radix-two FFT cost",
          "statement": "Let $M=2^q$ for an integer $q\\ge0$, and let $\\omega=e^{-2\\pi i/M}$ (with $\\omega=1$ when $M=1$). Define the forward DFT matrix $F\\in\\mathbb C^{M\\times M}$ by $F_{kj}=\\omega^{jk}$, where $^*$ denotes conjugate transpose. Then $F^*F=MI$, so the inverse DFT is $M^{-1}F^*$. The radix-two procedure defined on this page computes either transform exactly in $O(M\\log(2+M))$ complex arithmetic operations and $O(M)$ space. Consequently, for every integer $n\\ge1$, two polynomials of degree less than $n$ can be multiplied exactly in $O(n\\log(2+n))$ complex arithmetic operations and $O(n)$ space by zero-padding to a radix-two transform length at least $2n-1$.",
          "deps": [
            "alg-radix-two-fft"
          ],
          "dependency_level": 1,
          "strategy": "direct",
          "sources": {
            "references": [
